with cleaned as (select *, lower(location) as location_lower, cast(budget as int) as budget_int, coalesce(dept_name, 'DIRECT') as resolved_dept_name from departments where location is not null and budget between 2307000 and 4020000) select * from (select location, dept_name, budget_int from cleaned) src pivot (max(budget_int) as total, count(1) as cnt for dept_name in ('Sales' as sales, 'Finance' as finance, 'Legal' as legal))
